//! Faithful Markdown rendering after content validation. Complete procedures,
//! existing stable anchors, exact acquisitions, commands and evidence survive.
use crate::*;
use regex::Regex;
use serde_json::json;
use std::collections::BTreeSet;
pub fn page_nav()->String{format!("[INTA]({WIKI}) / [Decision desk]({WIKI}/Decision-Desk) · [Service map]({WIKI}/Service-Map) · [Playbooks]({WIKI}/Playbooks) · [Tools]({WIKI}/Tool-Directory) · [Methods]({WIKI}/Methods) · [Open hub]({HUB})")}
pub fn page_footer(reviewed:&str,wiki:bool)->Vec<String>{let mut l=lines!["","---","",format!("Editorial review: **{reviewed}** · [Review standard]({WIKI}/Knowledge-Standards) · [Suggest a correction]({REPO}/issues/new/choose)"),""];if !wiki {l.extend(lines![format!("[← All playbooks](README.md) · [Live Wiki]({WIKI}) · [Contribution guide]({REPO}/blob/main/CONTRIBUTING.md)"),""]);}l}
pub fn diagram_block(source:&str)->Vec<String>{lines!["```mermaid",source.trim_end(),"```",""]}
pub fn anchor(identity:&str)->String{format!("<a id=\"{identity}\"></a>")}
pub fn legacy_anchors(title:&str)->Vec<String>{let title=Regex::new(r"\[([^\]]+)\]\([^)]*\)").unwrap().replace_all(title,"$1").to_lowercase();let regex=Regex::new(r"[\p{L}\p{N}\p{M}_ -]").unwrap();let value=title.chars().filter(|c|regex.is_match(&c.to_string())).collect::<String>().replace(' ',"-");let plain=value.replace(['\u{fe0f}','\u{fe0e}'],"");let mut out=Vec::new();for id in [value,plain]{if !id.is_empty(){let a=anchor(&id);if !out.contains(&a){out.push(a);}}}out}
pub fn heading(level:usize,title:&str,previous:Option<&str>)->Vec<String>{let mut l=Vec::new();if let Some(p)=previous.filter(|p|*p!=title){l.extend(legacy_anchors(p));l.push(String::new());}l.extend(lines![format!("{} {title}","#".repeat(level)),""]);l}
pub fn scenario_link(id:&str,layout:&Value,absolute:bool,page:Option<&str>)->String{let config=&layout["jobs"][id];let dest=page.map(str::to_string).unwrap_or_else(||format!("Job-{id}"));format!("**[{} {}]({}{dest})**",s(config,"navigationIcon"),s(config,"navigationLabel"),if absolute{format!("{WIKI}/")}else{String::new()})}
fn action<'a>(entry:&'a Value,id:Option<&str>)->&'a Value{selected_tool_action(entry,id).expect("acquisition relationship was validated before rendering")}
pub fn tool_access_links(tool:&Value,access:&Value,all_routes:bool,action_id:Option<&str>)->String {let entry=&access[s(tool,"id")];let primary=action(entry,action_id);let mut links=lines![format!("[Official page]({})",s(entry,"officialUrl")),format!("**[{}]({})**",cell(&primary["label"]),s(primary,"url"))];let mut seen:BTreeSet<_>=[s(entry,"officialUrl"),s(primary,"url")].into_iter().collect();if all_routes{for action in std::iter::once(&entry["primary"]).chain(a(&entry["alternates"])){if seen.insert(s(action,"url")){links.push(format!("[{}]({})",cell(&action["label"]),s(action,"url")));}}if !seen.contains(s(tool,"downloadUrl")){links.push(format!("[All downloads / setup]({})",s(tool,"downloadUrl")));}}links.join(" · ")}
pub fn resolved_tool_choices(item:&Value,access:&Value)->Vec<Value>{let mut choices=a(&item["choices"]).to_vec();let id=s(item,"toolId");if !id.is_empty(){let selected=action(&access[id],item["toolAction"].as_str());if !choices.iter().any(|c|s(c,"toolId")==id&&action(&access[s(c,"toolId")],c["actionId"].as_str())["url"]==selected["url"]){let mut primary=json!({"toolId":id,"role":"Starting tool","why":item["why"],"freeUse":item["freeUse"],"evidenceUrls":item["evidenceUrls"]});if truth(&item["toolAction"]){primary["actionId"]=item["toolAction"].clone();}choices.push(primary);}}choices}
pub fn choice_links_markdown(choice:&Value,tools:&Value,access:&Value)->String{let tool=&tools[s(choice,"toolId")];let entry=&access[s(tool,"id")];let selected=action(entry,choice["actionId"].as_str());format!("**[{}]({})** · **[{}]({})**",s(tool,"name"),s(entry,"officialUrl"),cell(&selected["label"]),s(selected,"url"))}
pub fn tool_choices_markdown(item:&Value,tools:&Value,access:&Value)->Vec<String>{let choices=resolved_tool_choices(item,access);if choices.is_empty(){return vec![];}let mut l=lines![anchor("tool-choices"),"","## 🧰 Choose the tool for this job","","Choose by the task shown in the first column. Each option includes its acquisition route and access boundary.","","| Need | Official tool + exact action | Why this choice / access |","| --- | --- | --- |"];
 for c in choices{l.push(format!("| **{}** | {} | {} **Access:** {} |",cell(&c["role"]),choice_links_markdown(&c,tools,access),cell(&c["why"]),cell(&c["freeUse"])));}l.extend(lines!["",format!("**[Current selection evidence]({WIKI}/Current-Tool-Choices)**"),""]);l}
pub fn quick_start_markdown(quick:&Value,tools:&Value,layout:&Value,access:&Value)->String{let mut l=lines![anchor("free-tools"),"","## ⚡ What do you need to fix?","","**Choose your problem for the first three actions.** Tool names open the official page; download links identify the file and platform. Each role has its own visible choice. Built-in features link to their instructions.","","| Fix this | Choose the right tool · official page + exact action |","| --- | --- |"];
 for item in a(&quick["items"]){let icon=if !s(item,"icon").is_empty(){s(item,"icon")}else{s(&layout["jobs"][s(item,"jobId")],"navigationIcon")};let guide=format!("{WIKI}/{}",s(item,"wikiPage"));let mut actions=if item["guideOnly"]==true{lines![format!("No extra download needed · **[Open checklist]({guide})**")]}else{vec![]};for c in resolved_tool_choices(item,access){actions.push(format!("**{}:** {} ({})",cell(&c["role"]),choice_links_markdown(&c,tools,access),cell(&c["freeUse"])));}l.push(format!("| **[{icon} {}]({guide})** | {} |",cell(&item["label"]),actions.join("<br>")));}l.extend(lines!["",format!("Selection review: **{}** · [Complete tool directory]({WIKI}/Tool-Directory) · [Why these tools]({WIKI}/Free-Tool-Picks) · [Current tool choices]({WIKI}/Current-Tool-Choices)",s(quick,"reviewedAt")),""]);l.join("\n")}
pub fn replace_quick_start_block(content:&str,block:&str,source:&str)->Result<String>{ensure(content.matches(QUICK_START_START).count()==1&&content.matches(QUICK_START_END).count()==1,format!("{source}: exactly one quick-start marker pair is required"))?;let start=content.find(QUICK_START_START).unwrap()+QUICK_START_START.len();let end=content.find(QUICK_START_END).unwrap();ensure(end>=start,format!("{source}: quick-start markers are reversed"))?;Ok(format!("{}\n\n{}\n\n{}",&content[..start],block.trim(),&content[end..]))}
pub fn workspace_resources_markdown(workspace:&Value,tools:&Value,access:&Value,working_url:&str)->Vec<String>{let mut l=lines![anchor("working-kit"),"","## 🧰 Tools and links for this job","",format!("**[Open working view]({working_url})** · Keep the tool panel beside the instructions."),"",format!("**First move:** {}",s(workspace,"startHere")),""];let drivers:Vec<_>=a(&workspace["resources"]).iter().filter(|r|s(r,"kind")=="driver").collect();if !drivers.is_empty(){l.extend(lines![format!("**Driver shortcuts:** {}",drivers.iter().map(|r|format!("**[{}]({})**",cell(&r["label"]),s(r,"url"))).collect::<Vec<_>>().join(" · ")),""]);}if !a(&workspace["tools"]).is_empty(){l.extend(lines!["| Use this for | Official tool + exact action |","| --- | --- |"]);for selection in a(&workspace["tools"]){let tool=&tools[s(selection,"toolId")];l.push(format!("| {} | **[{}]({})** · {} |",cell(&selection["why"]),s(tool,"name"),s(&access[s(tool,"id")],"officialUrl"),tool_access_links(tool,access,false,selection["actionId"].as_str())));}l.push(String::new());}let mut groups:Vec<(&str,Vec<&Value>)>=vec![];for resource in a(&workspace["resources"]){let name=s(resource,"group");if let Some((_,resources))=groups.iter_mut().find(|(g,_)|*g==name){resources.push(resource);}else{groups.push((name,vec![resource]));}}for(group,resources)in groups{l.extend(lines![format!("### {group}"),"","| Open the exact resource | What to do there |","| --- | --- |"]);l.extend(resources.iter().map(|r|format!("| **[{}]({})** | {} |",cell(&r["label"]),s(r,"url"),cell(&r["description"]))));l.push(String::new());}l}
pub fn workspace_decisions_markdown(workspace:&Value)->Vec<String>{let mut l=lines![anchor("next-action"),"","## 🧭 Match the symptom","","| You see this | Do this next | You should get |","| --- | --- | --- |"];
 l.extend(a(&workspace["decisions"]).iter().map(|d|format!("| **{}** | {} | {} |",cell(&d["symptom"]),cell(&d["action"]),cell(&d["expected"]))));l.extend(lines!["","### ✅ Finish the job",""]);l.extend(a(&workspace["doneWhen"]).iter().map(|v|format!("- [ ] {}",t(v))));l.extend(lines!["",format!("**Change route when:** {}",a(&workspace["escalateWhen"]).iter().map(t).collect::<Vec<_>>().join(" · ")),""]);l}
pub fn quick_answer_markdown(item:&Value,tools:&Value,access:&Value,reviewed:&str,workspace:Option<&Value>)->String{let icon=item["icon"].as_str().unwrap_or("🛠️");let mut l=lines![page_nav(),"",format!("# {icon} {}",s(item,"label")),"",format!("**{}**",s(item,"firstStep")),""];l.extend(tool_choices_markdown(item,tools,access));if let Some(workspace)=workspace{let mut selected_workspace=workspace.clone();selected_workspace["startHere"]=item["firstStep"].clone();if item["guideOnly"]!=true{let mut selected=json!({"toolId":item["toolId"],"why":item["label"]});if truth(&item["toolAction"]){selected["actionId"]=item["toolAction"].clone();}let mut selections=vec![selected.clone()];selections.extend(a(&workspace["tools"]).iter().filter(|v|v["toolId"]!=selected["toolId"]||v["actionId"]!=selected["actionId"]).cloned());selected_workspace["tools"]=Value::Array(selections);}l.extend(workspace_resources_markdown(&selected_workspace,tools,access,&format!("{HUB}#job/{}/quick/{}",s(item,"jobId"),s(item,"id"))));l.extend(lines!["## ⚡ First three actions",""]);}l.extend(a(&item["quickSteps"]).iter().enumerate().map(|(n,step)|format!("{}. {}",n+1,t(step))));l.push(String::new());if item["guideOnly"]==true{l.extend(lines!["**No extra download needed.**",""]);}else{let tool=&tools[s(item,"toolId")];let e=&access[s(tool,"id")];let a=action(e,item["toolAction"].as_str());l.extend(lines![format!("**[{}]({})** · **[{}]({})**",s(tool,"name"),s(e,"officialUrl"),cell(&a["label"]),s(a,"url")),""]);}l.push(format!("**[Complete procedure]({WIKI}/Job-{})** · **[Specific fixes for this job]({HUB}#job/{}/quick/{}?section=fixes)** · **[Selection evidence]({WIKI}/Free-Tool-Picks)**",s(item,"jobId"),s(item,"jobId"),s(item,"id")));if let Some(w)=workspace{l.push(String::new());l.extend(workspace_decisions_markdown(w));}l.extend(page_footer(reviewed,true));l.join("\n")}
pub fn field_note_index(notes:&[Value])->Vec<String>{if notes.is_empty(){return vec![];}let mut l=lines!["### 🎯 Go straight to a specific fix",""];l.extend(notes.iter().map(|n|format!("- **[{}](#fix-{})** — {}",s(n,"title"),s(n,"id"),s(n,"symptom"))));l.push(String::new());l}
pub fn field_notes_markdown(notes:&[Value],tools:&Value,access:&Value,workspace:&Value)->Vec<String>{let mut l=lines![anchor("specific-fixes"),"","## 🎯 Specific fixes","","Choose the case that matches the evidence. Each case gives a first action, a short procedure and a result to prove.",""];for n in notes{l.extend(lines![anchor(&format!("fix-{}",s(n,"id"))),"",format!("### {}",s(n,"title")),"",format!("**Use when:** {}",s(n,"symptom")),"",format!("**Start here:** {}",s(n,"firstAction")),""]);for tid in a(&n["toolIds"]){let id=t(tid);let tool=&tools[id];let selection=a(&workspace["tools"]).iter().find(|v|s(v,"toolId")==id).unwrap_or(&Value::Null);l.extend(lines![format!("**[{}]({})** · {}",s(tool,"name"),s(&access[id],"officialUrl"),tool_access_links(tool,access,false,selection["actionId"].as_str())),""]);}l.extend(a(&n["steps"]).iter().enumerate().map(|(i,v)|format!("{}. {}",i+1,t(v))));if !a(&n["commands"]).is_empty(){l.extend(lines!["","#### ⚡ Quick commands",""]);for c in a(&n["commands"]){let language=if s(c,"shell").contains("PowerShell"){"powershell"}else if s(c,"shell").contains("Linux"){"bash"}else{"cmd"};l.extend(lines![format!("**{}** · {}",s(c,"label"),s(c,"shell")),"",s(c,"purpose"),"",format!("```{language}"),s(c,"code"),"```","",format!("> **Before running:** {}",s(c,"safety")),""]);if truth(&c["sourceUrl"]){l.extend(lines![format!("**Official reference:** [{}]({})",c["sourceTitle"].as_str().unwrap_or("Documentation"),s(c,"sourceUrl")),""]);}}}l.extend(lines!["",format!("**Prove it worked:** {}",s(n,"expected")),"",format!("**If this does not resolve it:** {}",s(n,"ifUnresolved")),"",format!("**Official evidence:** {} · Reviewed {}",a(&n["sourceUrls"]).iter().enumerate().map(|(i,u)|format!("[Source {}]({})",i+1,t(u))).collect::<Vec<_>>().join(" · "),s(n,"reviewedAt")),"","[Back to specific fixes](#specific-fixes) · [Full procedure](#walkthrough)",""]);}l}
pub fn command_reference(step:&Value,tools:&Value)->String{let command=s(step,"command").split_whitespace().next().unwrap_or("").to_lowercase();let name=step["commandName"].as_str().unwrap_or(&command);let url=s(step,"commandUrl");let mut links=lines![format!("[{name}]({url})")];if ["get-netipconfiguration","resolve-dnsname","test-computersecurechannel"].contains(&command.as_str()){links.push(format!("[PowerShell]({})",s(&tools["powershell"],"docsUrl")));}links.join(" · ")}
#[allow(clippy::too_many_arguments)]
pub fn job_markdown(job:&Value,tools:&Value,wiki:bool,layout:&Value,jobs:&Value,reviewed:&str,quick_items:&[Value],access:&Value,workspace:Option<&Value>,notes:&[Value])->String{
 let config=&layout["jobs"][s(job,"id")];let destination=|id:&str|if wiki{format!("{WIKI}/Job-{id}")}else{format!("{id}.md")};let mut l=lines![page_nav(),""];l.extend(heading(1,s(job,"title"),Some(&format!("{} {}",s(config,"icon"),s(job,"title")))));l.extend(lines![s(job,"summary"),"",format!("**{}** · {} · {} · {} steps",cell(&job["category"]),cell(&job["difficulty"]),cell(&job["estimatedTime"]),a(&job["steps"]).len()),"",format!("[Tools and useful links](#working-kit) · [Quick answer](#quick-answer) · [Next action](#next-action) · [Specific fixes](#specific-fixes) · [Decision route](#decision-route) · [Tools](#toolkit) · [Procedure](#walkthrough) · [Verification](#acceptance) · [Sources](#sources) · [Interactive checklist]({HUB}#job/{})",s(job,"id")),""]);
 if let Some(item)=quick_items.first(){l.extend(tool_choices_markdown(item,tools,access));}if s(job,"id")=="client-handoff"{l.extend(lines![format!("**[Open the dedicated nine-step Checklist tab]({HUB}#checklist)**"),""]);}if let Some(w)=workspace{l.extend(workspace_resources_markdown(w,tools,access,&format!("{HUB}#job/{}",s(job,"id"))));}if !quick_items.is_empty(){l.extend(lines![anchor("quick-answer"),"","## ⚡ Quick answer",""]);for item in quick_items{l.extend(lines![anchor(&format!("quick-{}",s(item,"id"))),"",format!("### {} {}",item["icon"].as_str().unwrap_or("🛠️"),s(item,"label")),"",format!("**{}**",s(item,"firstStep")),""]);l.extend(a(&item["quickSteps"]).iter().enumerate().map(|(n,v)|format!("{}. {}",n+1,t(v))));l.push(String::new());if item["guideOnly"]==true{l.extend(lines!["**No extra download needed.** Follow the checklist below.",""]);}else{let tool=&tools[s(item,"toolId")];l.extend(lines![format!("**[{}]({})** · {}",s(tool,"name"),s(&access[s(tool,"id")],"officialUrl"),tool_access_links(tool,access,false,item["toolAction"].as_str())),""]);}}}if let Some(w)=workspace{l.extend(workspace_decisions_markdown(w));}l.extend(field_note_index(notes));l.extend(lines!["> [!NOTE]",format!("> **Start here.** {}",s(job,"startHere")),"",anchor("decision-route"),""]);l.extend(heading(2,"🧭 Choose a route",Some("🧭 Choose the right branch")));l.extend(diagram_block(s(config,"diagram")));let mut routes=lines!["[Continue this workflow](#walkthrough)","[Acceptance checks](#acceptance)"];routes.extend(a(&job["related"]).iter().map(|v|format!("[{}]({})",s(&jobs[t(v)],"title"),destination(t(v)))));l.extend(lines![format!("**Route links:** {}",routes.join(" · ")),"","| Checkpoint | What to carry forward |","| --- | --- |"]);if let Some(map)=config["checkpoints"].as_object(){l.extend(map.iter().map(|(label,detail)|format!("| **{}** | {} |",cs(label),cell(detail))));}l.extend(lines!["",anchor("toolkit"),""]);l.extend(heading(2,"Recommended tools",Some("🧰 Build the right toolkit")));
 let ws=workspace.unwrap_or(&Value::Null);let mut recommended=Vec::new();for id in a(&job["tools"]).iter().map(t).chain(a(&ws["tools"]).iter().map(|v|s(v,"toolId"))){if !recommended.contains(&id){recommended.push(id);}}if !recommended.is_empty(){l.extend(lines!["Select a tool for the next diagnostic or repair step. Check its platform, access and licensing requirements before use.","","| Tool / official page + download | Use it for | Platform & access | Documentation |","| --- | --- | --- | --- |"]);for id in recommended{let tool=&tools[id];let selection=a(&ws["tools"]).iter().find(|v|s(v,"toolId")==id).unwrap_or(&Value::Null);l.push(format!("| **[{}]({})** · {} | {} | {}; {} | [Open guide]({}) |",s(tool,"name"),s(&access[id],"officialUrl"),tool_access_links(tool,access,false,selection["actionId"].as_str()),cell(selection.get("why").unwrap_or(&tool["bestFor"])),cell(&tool["platforms"]),cell(&tool["pricing"]),s(tool,"docsUrl")));}}else{l.push(format!("Use the approved private service record and the [intake and handoff template]({WIKI}/Technician-Handoff). No specialist application is required."));}
 l.extend(lines!["",anchor("walkthrough"),""]);l.extend(heading(2,"Procedure",Some("🪜 Work the case")));l.extend(lines!["Work in order, record the result of each step, and change route when the evidence calls for it.",""]);for(number,step)in a(&job["steps"]).iter().enumerate(){let identity=step_anchor(step,number+1).expect("validated step anchor");let old_title=identity.strip_prefix("step-").and_then(|n|n.parse::<usize>().ok()).map(|n|format!("{n:02} · {}",s(step,"title")));l.extend(lines![anchor(&identity),""]);l.extend(heading(3,&format!("{:02} · {}",number+1,s(step,"title")),old_title.as_deref()));l.extend(lines![format!("- [ ] {}",s(step,"detail")),""]);for shortcut in a(&step["shortcuts"]){if !shortcut["tool"].is_null(){let id=s(shortcut,"tool");l.push(format!("- [{}]({}) · {}",s(shortcut,"label"),s(&access[id],"officialUrl"),tool_access_links(&tools[id],access,false,None)));}else{let target=if !shortcut["job"].is_null(){destination(s(shortcut,"job"))}else{s(shortcut,"url").to_string()};l.push(format!("- [{}]({target})",s(shortcut,"label")));}}if !a(&step["shortcuts"]).is_empty(){l.push(String::new());}if truth(&step["command"]){l.extend(lines![format!("**{} · {}:**",cell(&step["commandShell"]),cell(&step["commandPurpose"])),"","```text",s(step,"command"),"```",""]);if truth(&step["commandSafety"]){l.extend(lines![format!("> **Before running:** {}",cell(&step["commandSafety"])),""]);}if truth(&step["commandUrl"]){l.extend(lines![format!("**Official command reference:** [{}]({})",cell(&step["commandName"]),s(step,"commandUrl")),""]);}l.extend(lines![format!("**Command legend:** {} · [Return to the step context](#{identity}).",command_reference(step,tools)),""]);}}
 l.extend(lines![anchor("acceptance"),""]);l.extend(heading(2,"Verification",Some("✅ Prove the result")));l.extend(a(&job["verify"]).iter().map(|v|format!("- [ ] {}",t(v))));l.extend(lines!["","> [!WARNING]","> **Pause this route and escalate when:**"]);l.extend(a(&job["stopIf"]).iter().map(|v|format!("> - {}",t(v))));if !notes.is_empty(){l.push(String::new());l.extend(field_notes_markdown(notes,tools,access,ws));}l.push(String::new());l.extend(heading(2,"Related playbooks",Some("🔀 Continue with the evidence")));if !a(&job["related"]).is_empty(){l.extend(lines!["| Next playbook | What it resolves |","| --- | --- |"]);for id in a(&job["related"]){let other=&jobs[t(id)];l.push(format!("| [{}]({}) | {} |",s(other,"title"),destination(t(id)),cell(&other["summary"])));}}l.extend(lines!["",anchor("sources"),""]);l.extend(heading(2,"Official sources",Some("🔎 Source trail")));l.extend(a(&job["sources"]).iter().map(|v|format!("- [{}]({})",s(v,"title"),s(v,"url"))));let reviewed=job["reviewedAt"].as_str().unwrap_or(reviewed);l.extend(lines!["",format!("Reviewed **{reviewed}**. Timing is a planning range. A successful command is evidence about that operation; acceptance belongs to the user’s original task."),""]);l.extend(page_footer(reviewed,wiki));l.join("\n")
}
